var $sqx_m49_lcd = screen("ore_screen", 0)
const $sqx_m49_scale = 2
var $sqx_m49_key = ""
var $sqx_m49_page = 0
var $sqx_m49_rows = 0
var $sqx_v31_mining_cargo = "!"
var $sqx_m49_ink = color(8, 14, 22)

function @sqx_m49_text($sqx_m49_x : number, $sqx_m49_y : number, $sqx_m49_size : number, $sqx_m49_colour : number, $sqx_m49_text : text)
	$sqx_m49_lcd.text_size($sqx_m49_size * $sqx_m49_scale)
	$sqx_m49_lcd.text_align(top_left)
	$sqx_m49_lcd.write($sqx_m49_x * $sqx_m49_scale, $sqx_m49_y * $sqx_m49_scale, $sqx_m49_colour, $sqx_m49_text)

function @sqx_m49_center_text($sqx_m49_cx : number, $sqx_m49_cy : number, $sqx_m49_font : number, $sqx_m49_colour : number, $sqx_m49_label : text)
	$sqx_m49_lcd.text_size($sqx_m49_font * $sqx_m49_scale)
	$sqx_m49_lcd.text_align(top_left)
	var $sqx_m49_fit = ($sqx_m49_lcd.width - 12) / max(size($sqx_m49_label) * $sqx_m49_lcd.char_w, 1)
	if $sqx_m49_fit < 1
		$sqx_m49_lcd.text_size($sqx_m49_font * $sqx_m49_scale * $sqx_m49_fit)
	$sqx_m49_lcd.write($sqx_m49_cx * $sqx_m49_scale - size($sqx_m49_label) * $sqx_m49_lcd.char_w / 2, $sqx_m49_cy * $sqx_m49_scale - $sqx_m49_lcd.char_h / 2, $sqx_m49_colour, $sqx_m49_label)

function @sqx_m49_rect($sqx_m49_x1 : number, $sqx_m49_y1 : number, $sqx_m49_x2 : number, $sqx_m49_y2 : number, $sqx_m49_border_colour : number, $sqx_m49_fill_colour : number)
	$sqx_m49_lcd.draw_rect($sqx_m49_x1 * $sqx_m49_scale, $sqx_m49_y1 * $sqx_m49_scale, $sqx_m49_x2 * $sqx_m49_scale, $sqx_m49_y2 * $sqx_m49_scale, $sqx_m49_border_colour, $sqx_m49_fill_colour)

function @sqx_m49_render()
	if !$sqx_sw49_power
		if $sqx_m49_key != "OFF"
			$sqx_m49_lcd.blank(black)
			$sqx_m49_key = "OFF"
		return
	var $sqx_m49_cargo = input_text("cargo-container", 0)
	if $sqx_m49_cargo != $sqx_v31_mining_cargo
		$sqx_m49_rows = 0
		foreach $sqx_m49_cargo ($sqx_m49_name, $sqx_m49_quantity)
			if $sqx_m49_quantity:number > 0
				$sqx_m49_rows += 1
		$sqx_v31_mining_cargo = $sqx_m49_cargo
	$sqx_m49_page = clamp($sqx_m49_page, 0, max(ceil($sqx_m49_rows / 4) - 1, 0))
	var $sqx_m49_frame = text("{},{},{},{},{}", $sqx_m49_cargo, $sqx_m49_page, $sqx_sw49_mine, input_number("left-anchor", 0), $sqx_sw49_notice)
	if $sqx_m49_frame == $sqx_m49_key
		return
	$sqx_m49_lcd.blank($sqx_m49_ink)
	@sqx_m49_center_text(75, 9, 1.1, orange, "MINING CARGO")
	@sqx_m49_center_text(75, 21, 0.8, white, text("ROCK {0} / 8000", $sqx_m49_cargo.Rock))
	var $sqx_m49_index = 0
	foreach $sqx_m49_cargo ($sqx_m49_item, $sqx_m49_value)
		var $sqx_m49_count = $sqx_m49_value:number
		if $sqx_m49_count > 0
			if ($sqx_m49_index >= $sqx_m49_page * 4) and ($sqx_m49_index < ($sqx_m49_page + 1) * 4)
				var $sqx_m49_y = 31 + mod($sqx_m49_index, 4) * 19
				@sqx_m49_text(6, $sqx_m49_y, 0.8, white, text("{} {0}", substring($sqx_m49_item, 0, 16), $sqx_m49_count))
				@sqx_m49_rect(6, $sqx_m49_y + 9, 144, $sqx_m49_y + 14, gray, color(18, 24, 32))
				var $sqx_m49_width = floor(clamp($sqx_m49_count / 8000, 0, 1) * 136)
				if $sqx_m49_width > 0
					@sqx_m49_rect(7, $sqx_m49_y + 10, 7 + $sqx_m49_width, $sqx_m49_y + 13, green, green)
			$sqx_m49_index += 1
	if $sqx_m49_rows == 0
		@sqx_m49_center_text(75, 57, 1, gray, "EMPTY")
	var $sqx_m49_status = $sqx_sw49_notice
	if input_number("left-anchor", 0)
		$sqx_m49_status = "LANDED"
		if $sqx_sw49_mine
			$sqx_m49_status = "MINING"
	elseif $sqx_m49_status == "UNLAND"
		$sqx_m49_status = "ANCHOR RELEASED"
	@sqx_m49_center_text(75, 112, 0.75, cyan, substring($sqx_m49_status, 0, 36))
	var $sqx_m49_border = color(120, 28, 36)
	if $sqx_sw49_mine
		$sqx_m49_border = green
	@sqx_m49_rect(64, 124, 86, 146, $sqx_m49_border, color(18, 24, 32))
	@sqx_m49_center_text(75, 135, 0.6, $sqx_m49_border, "MINE")
	@sqx_m49_rect(1, 124, 23, 146, cyan, $sqx_m49_ink)
	@sqx_m49_rect(127, 124, 149, 146, cyan, $sqx_m49_ink)
	@sqx_m49_center_text(12, 135, 1.1, cyan, "<")
	@sqx_m49_center_text(138, 135, 1.1, cyan, ">")
	$sqx_m49_key = $sqx_m49_frame

function @sqx_m49_click($sqx_m49_native_x : number, $sqx_m49_native_y : number)
	if !$sqx_sw49_power
		return
	var $sqx_m49_touch_x = $sqx_m49_native_x / $sqx_m49_scale
	var $sqx_m49_touch_y = $sqx_m49_native_y / $sqx_m49_scale
	if ($sqx_m49_touch_y < 124) or ($sqx_m49_touch_y >= 146)
		return
	if ($sqx_m49_touch_x >= 64) and ($sqx_m49_touch_x < 86)
		@sqx_sw49_action(10)
	elseif ($sqx_m49_touch_x >= 1) and ($sqx_m49_touch_x < 23)
		$sqx_m49_page = max($sqx_m49_page - 1, 0)
	elseif ($sqx_m49_touch_x >= 127) and ($sqx_m49_touch_x < 149)
		$sqx_m49_page = min($sqx_m49_page + 1, max(ceil($sqx_m49_rows / 4) - 1, 0))

timer frequency 5
	@sqx_m49_render()

click.$sqx_m49_lcd ($sqx_m49_click_x : number, $sqx_m49_click_y : number)
	@sqx_m49_click($sqx_m49_click_x, $sqx_m49_click_y)

var $sqx_tg47_lcd = screen("screen", 0)
var $sqx_tg47_bg = color(8, 14, 22)
var $sqx_tg47_display_key = ""
var $sqx_tg47_display_power = -1
var $sqx_tg47_hold_last = 0
var $sqx_tg47_hold_start = 0
var $sqx_tg47_hold_next = 0
var $sqx_tg47_hold_direction = 0

function @sqx_tg47_text($sqx_tg47_tx : number, $sqx_tg47_ty : number, $sqx_tg47_size : number, $sqx_tg47_tc : number, $sqx_tg47_label : text)
	$sqx_tg47_lcd.text_align(top_left)
	$sqx_tg47_lcd.text_size($sqx_tg47_size)
	$sqx_tg47_lcd.write($sqx_tg47_tx - size($sqx_tg47_label) * $sqx_tg47_lcd.char_w / 2, $sqx_tg47_ty - $sqx_tg47_lcd.char_h / 2, $sqx_tg47_tc, $sqx_tg47_label)

function @sqx_tg47_chrome()
	$sqx_tg47_lcd.draw_rect(0, 0, 300, 27, $sqx_tg47_bg, $sqx_tg47_bg)
	$sqx_tg47_lcd.draw_rect(0, 274, 300, 300, $sqx_tg47_bg, $sqx_tg47_bg)
	@sqx_tg47_text(150, 13, 1.3, orange, "TARGETS / BEACONS")
	if $sqx_tg47_delete
		$sqx_tg47_lcd.draw_rect(1, 275, 149, 299, cyan)
		$sqx_tg47_lcd.draw_rect(151, 275, 299, 299, red)
		@sqx_tg47_text(75, 287, 1.2, white, "CANCEL")
		@sqx_tg47_text(225, 287, 1.2, red, "DELETE")
	else
		repeat 4 ($sqx_tg47_button)
			$sqx_tg47_lcd.draw_rect($sqx_tg47_button * 75 + 1, 275, $sqx_tg47_button * 75 + 74, 299, cyan)
		@sqx_tg47_text(37, 287, 1.3, white, "PREV")
		@sqx_tg47_text(112, 287, 1.3, white, "NEXT")
		@sqx_tg47_text(187, 287, 1.6, green, "+")
		@sqx_tg47_text(262, 287, 1.6, red, "-")

; Dedicated left screen beside the keyboard; NAV/DOCK/ORE are unchanged.
function @sqx_tg47_frame()
	$sqx_tg47_lcd.blank($sqx_tg47_bg)
	if $sqx_tg47_delete
		@sqx_tg47_text(150, 65, 1.5, red, "CONFIRM DELETION")
		@sqx_tg47_text(150, 97, 1.3, white, text("LAST SLOT {0}", $sqx_tg47_main.size))
		if $sqx_tg47_names.size > 0
			var $sqx_tg47_last = $sqx_tg47_names.size - 1
			@sqx_tg47_text(150, 124, 1.1, cyan, substring($sqx_tg47_names.$sqx_tg47_last, 0, 35))
		@sqx_tg47_text(150, 170, 0.9, orange, "NAME, SIGNAL, LANDING, PERMISSION")
		@sqx_tg47_text(150, 190, 0.9, orange, "WILL ALL BE DELETED")
		@sqx_tg47_chrome()
		return
	@sqx_tg47_text(150, 41, 1.3, cyan, text("TARGET {0} / {0}", ($sqx_tg47_selected + 1) * ($sqx_tg47_main.size > 0), $sqx_tg47_main.size))
	if ($sqx_tg47_main.size == 0) or (!@sqx_tg47_valid())
		@sqx_tg47_text(150, 117, 1.2, white, "PRESS + TO ADD TARGET")
		@sqx_tg47_chrome()
		return
	var $sqx_tg47_name = $sqx_tg47_names.$sqx_tg47_selected
	var $sqx_tg47_signal = $sqx_tg47_main.$sqx_tg47_selected
	var $sqx_tg47_landing = $sqx_tg47_land.$sqx_tg47_selected
	repeat 3 ($sqx_tg47_row)
		var $sqx_tg47_y = 58 + $sqx_tg47_row * 48
		var $sqx_tg47_colour = gray
		var $sqx_tg47_label = "SIGNAL"
		var $sqx_tg47_value = $sqx_tg47_signal
		if $sqx_tg47_row == 1
			$sqx_tg47_label = "NAME"
			$sqx_tg47_value = $sqx_tg47_name
		elseif $sqx_tg47_row == 2
			$sqx_tg47_label = "LANDING SIGNAL / SLAVE"
			$sqx_tg47_value = $sqx_tg47_landing
		$sqx_tg47_lcd.draw_rect(6, $sqx_tg47_y, 294, $sqx_tg47_y + 43, $sqx_tg47_colour)
		@sqx_tg47_text(150, $sqx_tg47_y + 9, 0.8, cyan, $sqx_tg47_label)
		@sqx_tg47_text(150, $sqx_tg47_y + 29, 1, white, substring($sqx_tg47_value, 0, 44))
	if $sqx_tg47_focus > 0
		var $sqx_tg47_cursor_y = 58 + ($sqx_tg47_focus - 1) * 48
		$sqx_tg47_lcd.draw_rect(6, $sqx_tg47_cursor_y, 294, $sqx_tg47_cursor_y + 43, cyan)
		@sqx_tg47_text(282, $sqx_tg47_cursor_y + 29, 1.2, cyan, "_")
	var $sqx_tg47_permission = "[ ] COMMAND PERMISSION"
	if $sqx_tg47_commands.$sqx_tg47_selected
		$sqx_tg47_permission = "[X] COMMAND PERMISSION"
	@sqx_tg47_text(150, 215, 1, cyan, $sqx_tg47_permission)
	@sqx_tg47_text(150, 230, 0.7, gray, "SAVED ONLY / TRANSMISSION NOT ENABLED")
	var $sqx_tg47_status = "NO SIGNAL"
	if input_number("beacon", 5) and (time >= $sqx_tg47_receive_after)
		$sqx_tg47_status = "RECEIVING"
	if @sqx_tg47_locked()
		$sqx_tg47_status = "DOCK OWNS TARGET"
	@sqx_tg47_text(150, 246, 0.9, green, $sqx_tg47_status)
	@sqx_tg47_text(150, 263, 0.65, white, substring($sqx_tg47_notice, 0, 52))
	@sqx_tg47_chrome()

function @sqx_tg47_touch($sqx_tg47_x : number, $sqx_tg47_y : number)
	@sqx_tg47_boot()
	if $sqx_tg47_delete
		if $sqx_tg47_y >= 274
			if $sqx_tg47_x < 150
				$sqx_tg47_delete = 0
			else
				@sqx_tg47_remove_last()
		return
	if @sqx_tg47_locked()
		$sqx_tg47_notice = "DOCK OWNS TARGET"
		return
	if $sqx_tg47_y >= 274
		if $sqx_tg47_x < 75
			@sqx_tg47_move(-1)
		elseif $sqx_tg47_x < 150
			@sqx_tg47_move(1)
		elseif $sqx_tg47_x < 225
			@sqx_tg47_add()
		elseif $sqx_tg47_main.size > 0
			$sqx_tg47_delete = 1
			$sqx_tg47_focus = 0
			$sqx_tg47_wait_name = 0
	elseif ($sqx_tg47_y >= 58) and ($sqx_tg47_y < 202) and ($sqx_tg47_main.size > 0)
		$sqx_tg47_focus = floor(($sqx_tg47_y - 58) / 48) + 1
		$sqx_tg47_wait_name = 0
		$sqx_tg47_notice = "CLEAR KEYBOARD / ENTER NEW VALUE"
	elseif ($sqx_tg47_y >= 202) and ($sqx_tg47_y < 230) and ($sqx_tg47_main.size > 0) and @sqx_tg47_valid()
		$sqx_tg47_commands.$sqx_tg47_selected = !$sqx_tg47_commands.$sqx_tg47_selected

function @sqx_tg47_display_off()
	if $sqx_tg47_display_power != 0
		$sqx_tg47_lcd.blank(black)
	$sqx_tg47_display_power = 0
	$sqx_tg47_display_key = ""
	$sqx_tg47_focus = 0

function @sqx_tg47_display()
	@sqx_tg47_boot()
	if !@sqx_sw49_input("main-dash", 2)
		@sqx_tg47_display_off()
		return
	var $sqx_tg47_key = text("{},{},{},{},{},{}", $sqx_tg47_selected, $sqx_tg47_main.size, $sqx_tg47_delete, $sqx_tg47_focus, $sqx_tg47_notice, @sqx_tg47_locked())
	if ($sqx_tg47_main.size > 0) and @sqx_tg47_valid()
		$sqx_tg47_key = text("{},{},{},{},{},{}", $sqx_tg47_key, $sqx_tg47_names.$sqx_tg47_selected, $sqx_tg47_main.$sqx_tg47_selected, $sqx_tg47_land.$sqx_tg47_selected, $sqx_tg47_commands.$sqx_tg47_selected, input_number("beacon", 5) and (time >= $sqx_tg47_receive_after))
	if ($sqx_tg47_key != $sqx_tg47_display_key) or ($sqx_tg47_display_power != 1)
		@sqx_tg47_frame()
		$sqx_tg47_display_key = $sqx_tg47_key
		$sqx_tg47_display_power = 1

function @sqx_tg47_click($sqx_tg47_cx : number, $sqx_tg47_cy : number)
	if @sqx_sw49_input("main-dash", 2) and ($sqx_tg47_cx >= 0) and ($sqx_tg47_cx < 300) and ($sqx_tg47_cy >= 0) and ($sqx_tg47_cy < 300)
		$sqx_tg47_hold_direction = 0
		@sqx_tg47_touch($sqx_tg47_cx, $sqx_tg47_cy)

function @sqx_tg47_hold($sqx_tg47_hx : number, $sqx_tg47_hy : number)
	; Repeat only PREV/NEXT. ADD and DELETE/confirmation never repeat.
	if (!@sqx_sw49_input("main-dash", 2)) or ($sqx_tg47_hy < 274) or ($sqx_tg47_hy >= 300) or ($sqx_tg47_hx < 0) or ($sqx_tg47_hx >= 150) or $sqx_tg47_delete
		$sqx_tg47_hold_direction = 0
		return
	var $sqx_tg47_direction = -1
	if $sqx_tg47_hx >= 75
		$sqx_tg47_direction = 1
	if ($sqx_tg47_direction != $sqx_tg47_hold_direction) or ((time - $sqx_tg47_hold_last) > 0.2)
		$sqx_tg47_hold_direction = $sqx_tg47_direction
		$sqx_tg47_hold_start = time
		$sqx_tg47_hold_next = time + 0.35
	$sqx_tg47_hold_last = time
	if time >= $sqx_tg47_hold_next
		@sqx_tg47_move($sqx_tg47_direction)
		$sqx_tg47_hold_next = time + 0.125

timer frequency 10
	@sqx_tg47_display()

click.$sqx_tg47_lcd ($sqx_tg47_click_x : number, $sqx_tg47_click_y : number)
	@sqx_tg47_click($sqx_tg47_click_x, $sqx_tg47_click_y)

click_hold.$sqx_tg47_lcd ($sqx_tg47_held_x : number, $sqx_tg47_held_y : number)
	@sqx_tg47_hold($sqx_tg47_held_x, $sqx_tg47_held_y)

