; Cached LOAD widget below throttle; touch opens read-only mass/COM detail.
var $sqx_wt39_background = virtualscreen(150, 55)
var $sqx_wt39_graphics_ready = 0

; Presentation only. Physics, baseline and rotor-start limits remain kilograms.
function @sqx_wt39_pounds($sqx_wt39_kg : number) : number
	return $sqx_wt39_kg * 2.20462262185

function @sqx_wt39_text($sqx_wt39_canvas : screen, $sqx_wt39_tx : number, $sqx_wt39_ty : number, $sqx_wt39_font : number, $sqx_wt39_ink : number, $sqx_wt39_label : text)
	$sqx_wt39_canvas.text_align(top_left)
	$sqx_wt39_canvas.text_size($sqx_wt39_font)
	var $sqx_wt39_fit = min(1, 138 / max(size($sqx_wt39_label) * $sqx_wt39_canvas.char_w, 1))
	$sqx_wt39_canvas.text_size($sqx_wt39_font * $sqx_wt39_fit)
	$sqx_wt39_canvas.write($sqx_wt39_tx - size($sqx_wt39_label) * $sqx_wt39_canvas.char_w / 2, $sqx_wt39_ty - $sqx_wt39_canvas.char_h / 2, $sqx_wt39_ink, $sqx_wt39_label)

function @sqx_wt39_colour() : number
	if !$sqx_wt39_valid
		return gray
	if $sqx_wt39_load <= $sqx_wt39_green_limit
		return green
	if $sqx_wt39_load <= $sqx_wt39_yellow_limit
		return yellow
	return red

function @sqx_wt39_bar($sqx_wt39_bar_screen : screen, $sqx_wt39_left : number, $sqx_wt39_top : number, $sqx_wt39_width : number, $sqx_wt39_height : number)
	var $sqx_wt39_green_x = $sqx_wt39_left + $sqx_wt39_width * $sqx_wt39_green_limit / $sqx_wt39_load_limit
	var $sqx_wt39_yellow_x = $sqx_wt39_left + $sqx_wt39_width * $sqx_wt39_yellow_limit / $sqx_wt39_load_limit
	$sqx_wt39_bar_screen.draw_rect($sqx_wt39_left, $sqx_wt39_top, $sqx_wt39_green_x, $sqx_wt39_top + $sqx_wt39_height, color(16, 52, 30), color(16, 52, 30))
	$sqx_wt39_bar_screen.draw_rect($sqx_wt39_green_x, $sqx_wt39_top, $sqx_wt39_yellow_x, $sqx_wt39_top + $sqx_wt39_height, color(65, 56, 17), color(65, 56, 17))
	$sqx_wt39_bar_screen.draw_rect($sqx_wt39_yellow_x, $sqx_wt39_top, $sqx_wt39_left + $sqx_wt39_width, $sqx_wt39_top + $sqx_wt39_height, color(67, 22, 29), color(67, 22, 29))
	if $sqx_wt39_valid
		var $sqx_wt39_fill_x = $sqx_wt39_left + $sqx_wt39_width * clamp($sqx_wt39_load / $sqx_wt39_load_limit, 0, 1)
		if $sqx_wt39_load > 0
			$sqx_wt39_bar_screen.draw_rect($sqx_wt39_left, $sqx_wt39_top, min($sqx_wt39_fill_x, $sqx_wt39_green_x), $sqx_wt39_top + $sqx_wt39_height, green, green)
		if $sqx_wt39_load > $sqx_wt39_green_limit
			$sqx_wt39_bar_screen.draw_rect($sqx_wt39_green_x, $sqx_wt39_top, min($sqx_wt39_fill_x, $sqx_wt39_yellow_x), $sqx_wt39_top + $sqx_wt39_height, yellow, yellow)
		if $sqx_wt39_load > $sqx_wt39_yellow_limit
			$sqx_wt39_bar_screen.draw_rect($sqx_wt39_yellow_x, $sqx_wt39_top, $sqx_wt39_fill_x, $sqx_wt39_top + $sqx_wt39_height, red, red)
	else
		$sqx_wt39_bar_screen.draw_rect($sqx_wt39_left, $sqx_wt39_top, $sqx_wt39_left + $sqx_wt39_width, $sqx_wt39_top + $sqx_wt39_height, gray, color(18, 24, 32))

function @sqx_wt39_prepare_graphics()
	$sqx_wt39_background.blank($sqx_v31_background)
	@sqx_v31_round_box($sqx_wt39_background, 2, 2, 148, 52, 8, color(76, 93, 108))
	$sqx_wt39_background.draw_rect(58, 0, 92, 11, $sqx_v31_background, $sqx_v31_background)
	@sqx_wt39_text($sqx_wt39_background, 75, 5, 0.9, orange, "LOAD")
	if !$sqx_bt45_ready
		@sqx_bt45_prepare()
	; Reuse the battery display's exact cached half-size weight symbol.
	screen_copy($sqx_bt45_icons, $sqx_wt39_background, 32, 40, 10, 21, 16, 20)
	$sqx_wt39_graphics_ready = 1

function @sqx_wt39_compact($sqx_wt39_lcd : screen)
	if !$sqx_wt39_graphics_ready
		@sqx_wt39_prepare_graphics()
	screen_copy($sqx_wt39_background, $sqx_wt39_lcd, 0, 0, 0, 245, 150, 55)
	var $sqx_wt39_border = @sqx_wt39_colour()
	@sqx_wt39_bar($sqx_wt39_lcd, 35, 263, 100, 9)
	if $sqx_wt39_overload
		@sqx_v31_round_box($sqx_wt39_lcd, 2, 247, 148, 297, 8, red)
		$sqx_wt39_lcd.draw_rect(58, 245, 92, 256, $sqx_v31_background, $sqx_v31_background)
		@sqx_wt39_text($sqx_wt39_lcd, 75, 250, 0.9, orange, "LOAD")
	if $sqx_wt39_valid
		@sqx_wt39_text($sqx_wt39_lcd, 85, 285, 0.7, $sqx_wt39_border, text("{0} / {0} lb", @sqx_wt39_pounds($sqx_wt39_load), @sqx_wt39_pounds($sqx_wt39_load_limit)))
	else
		@sqx_wt39_text($sqx_wt39_lcd, 85, 285, 0.7, orange, "NO MASS SIGNAL")

function @sqx_wt39_details($sqx_wt39_detail : screen)
	$sqx_wt39_detail.blank($sqx_v31_background)
	@sqx_wt39_text($sqx_wt39_detail, 75, 14, 1.1, orange, "LOAD / MASS")
	if !$sqx_wt39_valid
		@sqx_wt39_text($sqx_wt39_detail, 75, 80, 1, orange, "MASS SENSOR")
		@sqx_wt39_text($sqx_wt39_detail, 75, 103, 0.8, white, "CHECK physics")
		@sqx_wt39_text($sqx_wt39_detail, 75, 130, 0.8, red, "START BLOCKED")
	else
		@sqx_wt39_text($sqx_wt39_detail, 75, 44, 1.2, white, text("TOTAL {0} lb", @sqx_wt39_pounds($sqx_wt39_mass)))
		@sqx_wt39_text($sqx_wt39_detail, 75, 68, 0.8, gray, text("EMPTY {0} lb", @sqx_wt39_pounds($sqx_wt39_empty_mass)))
		@sqx_wt39_text($sqx_wt39_detail, 75, 97, 0.9, @sqx_wt39_colour(), text("LOAD {0} / {0} lb", @sqx_wt39_pounds($sqx_wt39_load), @sqx_wt39_pounds($sqx_wt39_load_limit)))
		@sqx_wt39_bar($sqx_wt39_detail, 10, 117, 130, 10)
		var $sqx_wt39_shift = (!$sqx_sw49_rotors) and @sqx_wt39_same_pose()
		var $sqx_wt39_label = "COM / SENSOR"
		var $sqx_wt39_dx = $sqx_wt39_x
		var $sqx_wt39_dy = $sqx_wt39_y
		var $sqx_wt39_dz = $sqx_wt39_z
		if $sqx_wt39_shift
			$sqx_wt39_label = "COM / SHIFT"
			$sqx_wt39_dx -= $sqx_wt39_ref_x
			$sqx_wt39_dy -= $sqx_wt39_ref_y
			$sqx_wt39_dz -= $sqx_wt39_ref_z
		@sqx_wt39_text($sqx_wt39_detail, 75, 154, 0.95, orange, $sqx_wt39_label)
		@sqx_wt39_text($sqx_wt39_detail, 75, 181, 0.9, cyan, text("X {0.00}ft", $sqx_wt39_dx * 3.280839895))
		@sqx_wt39_text($sqx_wt39_detail, 75, 202, 0.9, cyan, text("Y {0.00}ft", $sqx_wt39_dy * 3.280839895))
		@sqx_wt39_text($sqx_wt39_detail, 75, 223, 0.9, cyan, text("Z {0.00}ft", $sqx_wt39_dz * 3.280839895))
		var $sqx_wt39_reference = "EMPTY REF PENDING"
		if $sqx_wt39_ref_valid
			$sqx_wt39_reference = "MATCH POSE FOR SHIFT"
		if $sqx_wt39_shift
			$sqx_wt39_reference = "AT EMPTY REF POSE"
		@sqx_wt39_text($sqx_wt39_detail, 75, 247, 0.7, gray, $sqx_wt39_reference)
	@sqx_wt39_text($sqx_wt39_detail, 75, 283, 0.8, cyan, "TAP TO RETURN")

