; Read-only throttle/collective observer. Never changes the lever or flight PID.
var $sqx_th49_lcd = screen("main-dash", 0)
var $sqx_th49_background = virtualscreen(150, 300)
var $sqx_th49_ready = 0
var $sqx_th49_power = -1
var $sqx_th49_key = ""
var $sqx_th49_ink = color(8, 14, 22)
var $sqx_th49_magenta = color(255, 0, 220)

function @sqx_th49_text($sqx_th49_x : number, $sqx_th49_y : number, $sqx_th49_size : number, $sqx_th49_colour : number, $sqx_th49_label : text)
	$sqx_th49_lcd.text_align(top_left)
	$sqx_th49_lcd.text_size($sqx_th49_size)
	$sqx_th49_lcd.write($sqx_th49_x - size($sqx_th49_label) * $sqx_th49_lcd.char_w / 2, $sqx_th49_y - $sqx_th49_lcd.char_h / 2, $sqx_th49_colour, $sqx_th49_label)

function @sqx_th49_prepare()
	$sqx_th49_background.blank($sqx_th49_ink)
	$sqx_th49_background.text_align(top_left)
	$sqx_th49_background.text_size(1.1)
	$sqx_th49_background.write(48.6, 7, cyan, "THROTTLE")
	$sqx_th49_background.draw_rect(72, 45, 78, 200, gray, color(18, 24, 32))
	repeat 9 ($sqx_th49_tick)
		var $sqx_th49_y = 45 + $sqx_th49_tick * 19.375
		var $sqx_th49_half_width = 7
		if mod($sqx_th49_tick, 2) == 0
			$sqx_th49_half_width = 11
			var $sqx_th49_number = text("{0}", 100 - $sqx_th49_tick * 25)
			$sqx_th49_background.text_size(0.8)
			$sqx_th49_background.write(42 - size($sqx_th49_number) * $sqx_th49_background.char_w, $sqx_th49_y - 3.2, white, $sqx_th49_number)
		$sqx_th49_background.draw_line(75 - $sqx_th49_half_width, $sqx_th49_y, 75 + $sqx_th49_half_width, $sqx_th49_y, gray)
	$sqx_th49_ready = 1

function @sqx_th49_render()
	if !@sqx_sw49_input("main-dash", 2)
		if $sqx_th49_power != 0
			$sqx_th49_lcd.blank(black)
		$sqx_th49_power = 0
		$sqx_th49_key = ""
		return
	if !$sqx_th49_ready
		@sqx_th49_prepare()
	@sqx_wt39_sample(0)
	; SET is the actual lever value; AP already mirrors its output into that lever.
	; AP is the existing signed collective command ($throt), not rotor RPM/power.
	var $sqx_th49_setting = round(clamp(input_number("thrust", 0), -1, 1) * 100)
	var $sqx_th49_command = round(clamp($throt, -1, 1) * 100)
	var $sqx_th49_ap = @sqx_ui49b_ap_controlling()
	var $sqx_th49_actual_fpm = round(input_number("nav", 1) * 196.8503937 / 10) * 10
	var $sqx_th49_request_fpm = round($sqx_rx45_vs * 196.8503937 / 10) * 10
	var $sqx_th49_frame = text("{},{},{},{},{}", $sqx_th49_setting, $sqx_th49_command, $sqx_th49_ap, $sqx_th49_actual_fpm, $sqx_th49_request_fpm)
	$sqx_th49_frame = text("{},{},{0},{0},{},{}", $sqx_th49_frame, $sqx_wt39_page, $sqx_wt39_mass, $sqx_wt39_load, $sqx_wt39_valid, $sqx_wt39_overload)
	if $sqx_wt39_page
		$sqx_th49_frame = text("{},{},{},{0.00},{0.00},{0.00},{}", $sqx_th49_frame, $sqx_wt39_ref_valid, (!$sqx_sw49_rotors) and @sqx_wt39_same_pose(), $sqx_wt39_x * 3.280839895, $sqx_wt39_y * 3.280839895, $sqx_wt39_z * 3.280839895, $sqx_sw49_rotors)
	if ($sqx_th49_power == 1) and ($sqx_th49_frame == $sqx_th49_key)
		return
	if $sqx_wt39_page
		@sqx_wt39_details($sqx_th49_lcd)
		$sqx_th49_key = $sqx_th49_frame
		$sqx_th49_power = 1
		return
	screen_copy($sqx_th49_background, $sqx_th49_lcd, 0, 0, 0, 0, 150, 300)
	@sqx_th49_text(42, 30, 0.95, white, text("SET {0}%", $sqx_th49_setting))
	var $sqx_th49_setting_y = 122.5 - $sqx_th49_setting * 0.775
	$sqx_th49_lcd.draw_triangle(60, $sqx_th49_setting_y - 5, 71, $sqx_th49_setting_y, 60, $sqx_th49_setting_y + 5, white, white)
	if $sqx_th49_ap
		@sqx_th49_text(114, 30, 0.95, $sqx_th49_magenta, text("AP {0}%", $sqx_th49_command))
		var $sqx_th49_command_y = 122.5 - $sqx_th49_command * 0.775
		$sqx_th49_lcd.draw_triangle(90, $sqx_th49_command_y - 5, 79, $sqx_th49_command_y, 90, $sqx_th49_command_y + 5, $sqx_th49_magenta, $sqx_th49_magenta)
		@sqx_th49_text(75, 216, 0.85, $sqx_th49_magenta, text("CMD {0} FPM", $sqx_th49_request_fpm))
	else
		@sqx_th49_text(114, 30, 0.95, gray, "AP --")
	@sqx_th49_text(75, 235, 0.85, white, text("V/S {0} FPM", $sqx_th49_actual_fpm))
	@sqx_wt39_compact($sqx_th49_lcd)
	$sqx_th49_key = $sqx_th49_frame
	$sqx_th49_power = 1

timer frequency 10
	@sqx_th49_render()

click.$sqx_th49_lcd ($sqx_wt39_touch_x : number, $sqx_wt39_touch_y : number)
	if $sqx_sw49_power and (($sqx_wt39_touch_y >= 245) or $sqx_wt39_page)
		$sqx_wt39_page = !$sqx_wt39_page
		@sqx_wt39_sample(1)
		$sqx_th49_key = ""
